3	/**
4	 * Membership level rule: maps a {@link MembershipPoints} total to a level of 1 (0-1 points),
5	 * 2 (2-3), 3 (4-5) or 4 (6 or more). Owns only that mapping; the factors that earn points, and
6	 * their weights, live in the small factor classes behind {@link MembershipPoints}.
7	 */
8	public final class MembershipLevel {
9	
10	    private MembershipLevel() {
11	    }
12	
13	    public static int of(int points) {
14	        if (points >= 6) {
15	            return 4;
16	        }
17	        if (points >= 4) {
18	            return 3;
19	        }
20	        if (points >= 2) {
21	            return 2;
22	        }
23	        return 1;
24	    }
25	}
