5	/**
6	 * Fiscal-year calendar: the fiscal year starts on 1 July and is labelled by the calendar
7	 * year it ends in (so 2025-07-01..2026-06-30 is fiscal year 2026 / {@code FY26}). Owns the
8	 * single 1-July rule that the membership number, {@link TenureFactor} and the {@code fiscalYear}
9	 * response field all share.
10	 */
11	public final class FiscalYear {
12	
13	    private FiscalYear() {
14	    }
15	
16	    /** The fiscal year of {@code date} as a number — the calendar year the fiscal year ends in. */
17	    public static int of(LocalDate date) {
18	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
19	    }
20	
21	    /** The fiscal-year label {@code FY<YY>} for {@code date}. */
22	    public static String label(LocalDate date) {
23	        return String.format("FY%02d", of(date) % 100);
24	    }
25	}
